   648	static exr_result_t
   649	create_attr_block (
   650	    exr_context_t     ctxt,
   651	    exr_attribute_t** attr,
   652	    size_t            dblocksize,
   653	    int32_t           data_len,
   654	    uint8_t**         data_ptr,
   655	    const char*       name,
   656	    int32_t           nlen,
   657	    const char*       type,
   658	    int32_t           tlen)
   659	{
   660	    size_t           alignpad1, alignpad2;
   661	    size_t           attrblocksz = sizeof (exr_attribute_t);
   662	    uint8_t*         ptr;
   663	    exr_attribute_t* nattr;
   664	    exr_attribute_t  nil = {0};
   665	    // not all compilers have this :(
   666	    //const size_t ptralign = _Alignof(void*);
   667	    const size_t ptralign = 8;
   668	
   669	    if (nlen > 0) attrblocksz += (size_t) (nlen + 1);
   670	    if (tlen > 0) attrblocksz += (size_t) (tlen + 1);
   671	
   672	    if (dblocksize > 0)
   673	    {
   674	        alignpad1 = ptralign - (attrblocksz % ptralign);
   675	        if (alignpad1 == ptralign) alignpad1 = 0;
   676	        attrblocksz += alignpad1;
   677	        attrblocksz += dblocksize;
   678	    }
   679	    else
   680	        alignpad1 = 0;
   681	
   682	    if (data_len > 0)
   683	    {
   684	        /* align the extra data to a pointer */
   685	        alignpad2 = ptralign - (attrblocksz % ptralign);
   686	        if (alignpad2 == ptralign) alignpad2 = 0;
   687	        attrblocksz += alignpad2;
   688	        attrblocksz += (size_t) data_len;
   689	    }
   690	    else
   691	        alignpad2 = 0;
   692	
   693	    ptr = (uint8_t*) ctxt->alloc_fn (attrblocksz);
   694	    if (!ptr) return ctxt->standard_error (ctxt, EXR_ERR_OUT_OF_MEMORY);
   695	
   696	    nattr  = (exr_attribute_t*) ptr;
   697	    *nattr = nil;
   698	    *attr  = nattr;
   699	    ptr += sizeof (exr_attribute_t);
   700	    if (nlen > 0)
   701	    {
   702	        memcpy (ptr, name, (size_t) (nlen + 1));
   703	        nattr->name        = (char*) ptr;
   704	        nattr->name_length = (uint8_t) nlen;
   705	
   706	        ptr += nlen + 1;
   707	    }
   708	    if (tlen > 0)
   709	    {
   710	        memcpy (ptr, type, (size_t) (tlen + 1));
   711	        nattr->type_name        = (char*) ptr;
   712	        nattr->type_name_length = (uint8_t) tlen;
   713	
   714	        ptr += tlen + 1;
   715	    }
   716	    ptr += alignpad1;
   717	    if (dblocksize > 0)
   718	    {
   719	        nattr->rawptr = ptr;
   720	        ptr += dblocksize;
   721	    }
   722	    if (data_ptr)
   723	    {
   724	        if (data_len > 0)
   725	        {
   726	            ptr += alignpad2;
   727	            *data_ptr = ptr;
   728	        }
   729	        else
   730	            *data_ptr = NULL;
   731	    }
   732	    return EXR_ERR_SUCCESS;
   733	}
